void config_biome(uint32_t i, channels::boundary_biome &g) {
  switch (i) {
    case 0: config_biome_alpine(g); return;
    case 1: config_biome_boreal(g); return;
    case 2: config_biome_desert(g); return;
    case 3: config_biome_mediterranean(g); return;
    case 4: config_biome_temperate(g); return;
    case 5: config_biome_tropical(g); return;
    case 6: config_biome_volcanic(g); return;
  }
}

// The game's own hull (foundry_hull_cell records) in place of the entry's cells.
void hull_from_cells(const std::vector<uint8_t> &payload, channels::boundary_hull &h) {
  const size_t n = payload.size() / sizeof(foundry_hull_cell);
  h.cells.clear();
  h.edges.clear();
  h.heights.clear();
  h.rises.clear();
  h.opening_cells.clear();
  h.opening_kinds.clear();
  h.opening_widths.clear();
  for (size_t i = 0; i < n; ++i) {
    foundry_hull_cell c;
    std::memcpy(&c, payload.data() + i * sizeof c, sizeof c);
    h.cells.push_back(c.q);
    h.cells.push_back(c.r);
    h.edges.push_back(static_cast<uint32_t>(c.edge));
    h.heights.push_back(c.height);
    h.rises.push_back(c.rise);
    if (c.opening) {  // a road or river leaving through it
      h.opening_cells.push_back(c.q);
      h.opening_cells.push_back(c.r);
      h.opening_kinds.push_back(c.opening - 1);
      h.opening_widths.push_back(c.opening_width ? c.opening_width : 1u);
    }
  }
}

