int foundry_boundary_hull_find(const char *name) {
  static const char *const names[] = {"around_coast", "around_forest", "around_highland", "around_jungle", "around_marsh", "around_mountains", "around_valley", "bay", "canyon", "coast", "glade", "jungle_clearing", "l_shape", "marsh_edge", "mountain_pass", "plateau", "shape_hexagon", "shape_river_valley", "valley"};
  for (int i = 0; name && i < 19; ++i)
    if (std::strcmp(names[i], name) == 0) return i;
  return -1;
}

int foundry_boundary_biome_find(const char *name) {
  static const char *const names[] = {"alpine", "boreal", "desert", "mediterranean", "temperate", "tropical", "volcanic"};
  for (int i = 0; name && i < 7; ++i)
    if (std::strcmp(names[i], name) == 0) return i;
  return -1;
}

int foundry_boundary_season_find(const char *name) {
  static const char *const names[] = {"winter", "spring", "summer", "fall"};
  for (int i = 0; name && i < 4; ++i)
    if (std::strcmp(names[i], name) == 0) return i;
  return -1;
}

int foundry_boundary_detail_find(const char *name) {
  static const char *const names[] = {"high", "medium", "low"};
  for (int i = 0; name && i < 3; ++i)
    if (std::strcmp(names[i], name) == 0) return i;
  return -1;
}

foundry_status foundry_boundary_get_result(foundry_runtime *rt, foundry_instance instance, foundry_boundary_result *out) {
  uint32_t bits = 0;
  const runtime::Status st = rt->world.result(instance, bits);
  if (st != runtime::Status::ok) return foundry_status_of(st);
  if (!out) return FOUNDRY_OK;
  out->ready = (bits & runtime::World::kResultReady) != 0;
  return FOUNDRY_OK;
}

